const rows=[...CURATED.map(v=>({name:v[0],scientific:v[1],family:v[2],band:v[3]})),...FISH_DATA.filter(v=>!curatedNames.has(v[0])).map((v,i)=>({name:v[0],scientific:v[0],family:v[1],sourceKey:v[2],band:Math.min(19,Math.floor(i/16))}))];
export const SPECIES=rows.slice(0,320).map((f,i)=>{let hash=0;for(const c of f.scientific)hash=(Math.imul(hash,31)+c.charCodeAt(0))>>>0;
 const hue=hash%360,rank=i===0?1:i===7?3:hash%100<48?1:hash%100<78?2:hash%100<93?3:hash%100<99?4:5,rare=rank>=3;
 return {...f,rank,baseGrams:i===0?100:50+hash%25000,intrinsic:80+hash%420,spawnWeight:[0,40,15,5,2,1][rank],id:'fish-'+f.scientific.replaceAll(' ','-'),color:`hsl(${hue} 46% 68%)`,fin:`hsl(${hue} 30% 42%)`,size:11+hash%12,speed:i===0?24:16+hash%24,value:90+f.band*35+hash%80,rarity:['','よく見かける','やや珍しい','希少','非常に希少','伝説級'][rank],shape:(i<24?i===2:hash%5===0)?'round':'fish',minDepth:200+f.band*300,maxDepth:f.band===19?Infinity:1100+f.band*300,note:'実在する魚。出現深度・描画・能力値はゲーム用です。'};
});
